/** The exact key set this response's wire body carries; the correlation identifier is not among them, because it travels in the envelope. */
export const ApprovalRefused_BODY_FIELDS: readonly string[] = [
  "refusal",
];

export function decodeApprovalRefused(request_id: RequestId, body: JsonValue): ApprovalRefused {
  const fields = exactFields(body, ApprovalRefused_BODY_FIELDS, APPROVAL_INVALID_BODY);
  return {
    refusal: refuse(APPROVAL_UNKNOWN_ENUM_VALUE, () => decodeApprovalRefusal(bodyString(fields, "refusal", APPROVAL_INVALID_BODY))),
    request_id: request_id,
  };
}

/**
 * Kinds this protocol version defines that this file does not decode.
 *
 * They are neither refused nor guessed at: a peer that sent one sent something
 * defined, and a client told otherwise might act on the lie. The body is not
 * handed back, because nothing here has validated it.
 */
export const APPROVAL_RESPONSE_KINDS_NOT_DECODED = [] as const;
export type UndecodedApprovalResponseKind = (typeof APPROVAL_RESPONSE_KINDS_NOT_DECODED)[number];
export function isUndecodedApprovalResponseKind(value: string): value is UndecodedApprovalResponseKind {
  return (APPROVAL_RESPONSE_KINDS_NOT_DECODED as readonly string[]).includes(value);
}

/** Every response this file can hand a caller. */
export type ApprovalResponse =
  | {readonly kind: "approval_conflict"; readonly value: ApprovalConflict}
  | {readonly kind: "approval_detail_result"; readonly value: ApprovalDetailView}
  | {readonly kind: "approval_list_result"; readonly value: ApprovalListPage}
  | {readonly kind: "approval_recorded"; readonly value: ApprovalReceipt}
  | {readonly kind: "refused"; readonly value: ApprovalRefused}
  | {readonly kind: "undecoded"; readonly request_id: RequestId; readonly response_kind: UndecodedApprovalResponseKind};

export function assertNeverApprovalResponse(value: never): never {
  throw new ValidationError("ApprovalResponse", `unhandled variant: ${JSON.stringify(value)}`);
}

/**
 * Decode one canonical response payload.
 *
 * The payload is the framed transport's payload, without its length prefix.
 * The envelope is admitted first and on both axes: a name this file does not
 * implement and a major version outside its range are different refusals, and
 * neither is downgraded into the other.
 */
export function decodeApprovalResponse(payload: Uint8Array): ApprovalResponse {
  const message = decodeMessageAdmitted(payload, [
    {protocol: APPROVAL_PROTOCOL, minVersion: APPROVAL_PROTOCOL_VERSION, maxVersion: APPROVAL_PROTOCOL_VERSION},
  ]);
  const request_id = refuseField(APPROVAL_FIELD_INVALID, APPROVAL_FIELD_GRAMMAR, () =>
    RequestId(message.envelope.requestId),
  );
  const kind = message.envelope.kind;
  if (isUndecodedApprovalResponseKind(kind)) {
    return {kind: "undecoded", request_id, response_kind: kind};
  }
  switch (kind) {
    case APPROVAL_APPROVAL_CONFLICT_RESPONSE_KIND:
      return {kind: APPROVAL_APPROVAL_CONFLICT_RESPONSE_KIND, value: decodeApprovalConflict(request_id, message.body)};
    case APPROVAL_APPROVAL_DETAIL_RESULT_RESPONSE_KIND:
      return {kind: APPROVAL_APPROVAL_DETAIL_RESULT_RESPONSE_KIND, value: decodeApprovalDetailView(request_id, message.body)};
    case APPROVAL_APPROVAL_LIST_RESULT_RESPONSE_KIND:
      return {kind: APPROVAL_APPROVAL_LIST_RESULT_RESPONSE_KIND, value: decodeApprovalListPage(request_id, message.body)};
    case APPROVAL_APPROVAL_RECORDED_RESPONSE_KIND:
      return {kind: APPROVAL_APPROVAL_RECORDED_RESPONSE_KIND, value: decodeApprovalReceipt(request_id, message.body)};
    case APPROVAL_REFUSED_RESPONSE_KIND:
      return {kind: APPROVAL_REFUSED_RESPONSE_KIND, value: decodeApprovalRefused(request_id, message.body)};
    default:
      throw new RefusalError(
        APPROVAL_UNKNOWN_KIND,
        "message kind is not defined by this protocol version",
      );
  }
}
